#include <stdio.h>
#include <stdint.h>
uint16_t crc16_hdlc(const unsigned char *data, size_t len) {
    uint16_t crc = 0xFFFF;               // initial value
    for (size_t i = 0; i < len; ++i) {
        crc ^= data[i];
        for (int j = 0; j < 8; ++j) {
            if (crc & 1)
                crc = (crc >> 1) ^ 0xA001; // reflected 0x8005 (HDLC)
            else
                crc >>= 1;
        }
    }
    return crc; // xorOut = 0x0000, no final inversion
}
int main(){
    unsigned char pkt[] = {0xFF,0x03,0xAB};
    uint16_t fcs = crc16_hdlc(pkt,3);
    printf("%04X\n", fcs);
    return 0;
}
